def validateStackSequences(pushed: list[int], popped: list[int]) -> bool:
    stack = []
    pop_idx = 0
    for val in pushed:
        stack.append(val)
        while stack and pop_idx < len(popped) and stack[-1] == popped[pop_idx]:
            stack.pop()
            pop_idx += 1
    return pop_idx == len(popped)

